  24:             (matches.has(&flags::REVERSE)?, FFF::Reverse),
  25:             (matches.has(&flags::ONLY_DIRS)?, FFF::OnlyDirs),
  26:             (matches.has(&flags::ONLY_FILES)?, FFF::OnlyFiles),
  27:             (matches.has(&flags::NO_SYMLINKS)?, FFF::NoSymlinks),
  28:             (matches.has(&flags::SHOW_SYMLINKS)?, FFF::ShowSymlinks),
  29:             (matches.has(&flags::DIRS_LAST)?, FFF::ListDirsLast),
  30:             (matches.has(&flags::DIRS_FIRST)?, FFF::ListDirsFirst),
  31:         ] {
  32:             if *has {
  33:                 filter_flags.push(flag.clone());
  34:             }
  35:         }
