  37:         #[rustfmt::skip]
  38:         return Ok(Self {
  39:             no_symlinks:      filter_flags.contains(&FFF::NoSymlinks),
  40:             show_symlinks:    filter_flags.contains(&FFF::ShowSymlinks),
  41:             flags:            filter_flags,
  42:             sort_field:       SortField::deduce(matches)?,
  43:             dot_filter:       DotFilter::deduce(matches)?,
  44:             ignore_patterns:  IgnorePatterns::deduce(matches)?,
  45:             git_ignore:       GitIgnore::deduce(matches)?,
