  50: impl SortField {
  51:     /// Determines which sort field to use based on the `--sort` argument.
  52:     /// This argument’s value can be one of several flags, listed above.
  53:     /// Returns the default sort field if none is given, or `Err` if the
  54:     /// value doesn’t correspond to a sort field we know about.
  55:     fn deduce(matches: &MatchedFlags<'_>) -> Result<Self, OptionsError> {
  56:         let Some(word) = matches.get(&flags::SORT)? else {
  57:             return Ok(Self::default());
  58:         };
  59: 
  60:         // Get String because we can’t match an OsStr
  61:         let Some(word) = word.to_str() else {
  62:             return Err(OptionsError::BadArgument(&flags::SORT, word.into()));
  63:         };
  64: 
  65:         let field = match word {
  66:             "name" | "filename" => Self::Name(SortCase::AaBbCc),
  67:             "Name" | "Filename" => Self::Name(SortCase::ABCabc),
  68:             ".name" | ".filename" => Self::NameMixHidden(SortCase::AaBbCc),
  69:             ".Name" | ".Filename" => Self::NameMixHidden(SortCase::ABCabc),
  70:             "size" | "filesize" => Self::Size,
  71:             "ext" | "extension" => Self::Extension(SortCase::AaBbCc),
  72:             "Ext" | "Extension" => Self::Extension(SortCase::ABCabc),
  73: 
  74:             // “new” sorts oldest at the top and newest at the bottom; “old”
  75:             // sorts newest at the top and oldest at the bottom. I think this
  76:             // is the right way round to do this: “size” puts the smallest at
  77:             // the top and the largest at the bottom, doesn’t it?
  78:             "date" | "time" | "mod" | "modified" | "new" | "newest" => Self::ModifiedDate,
  79: 
  80:             // Similarly, “age” means that files with the least age (the
  81:             // newest files) get sorted at the top, and files with the most
  82:             // age (the oldest) at the bottom.
  83:             "age" | "old" | "oldest" => Self::ModifiedAge,
  84: 
  85:             "ch" | "changed" => Self::ChangedDate,
  86:             "acc" | "accessed" => Self::AccessedDate,
  87:             "cr" | "created" => Self::CreatedDate,
  88:             #[cfg(unix)]
  89:             "inode" => Self::FileInode,
  90:             "type" => Self::FileType,
  91:             "none" => Self::Unsorted,
  92:             _ => {
  93:                 return Err(OptionsError::BadArgument(&flags::SORT, word.into()));
  94:             }
  95:         };
  96: 
  97:         Ok(field)
  98:     }
  99: }
