  92: /// Convert between Unicode width and width in chars to use in format!.
  93: /// ex: in Japanese, 月 is one character, but it has the width of two.
  94: /// For alignment purposes, we take the real display width into account.
  95: /// So, `MAXIMUM_MONTH_WIDTH` (“12月”) = 4, but if we use `{:4}` in format!,
  96: /// it will add a space (“ 12月”) because format! counts characters.
  97: /// Conversely, a char can have a width of zero (like combining diacritics)
  98: fn short_month_padding(max_month_width: usize, month: &str) -> usize {
  99:     let shift = month.chars().count() as isize - UnicodeWidthStr::width(month) as isize;
 100:     (max_month_width as isize + shift) as usize
 101: }
